<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="description" content="Reset Password - Nutriqube Enterprise Nutrition Analytics">
    <title>Reset Password - Nutriqube</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Geist:wght@400;500;600;700&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css">
    <link rel="stylesheet" href="/static/css/premium-login.css">
</head>
<body class="login-page">
    <div class="login-layout">
        <div class="login-branding" style="background-image: url(/images/landing/image3.jpg);"><div class="branding-container"><a href="/" class="branding-logo"><img src="/images/logo/nutri.png" alt="Nutriqube logo" /><span>Nutriqube</span></a><div class="branding-bottom-content"><h3>Support When You Need It</h3><p>Need access? <a href="/?contact=open">Contact our team</a></p></div></div><div class="branding-background"><div class="gradient-orb gradient-orb-1"></div><div class="gradient-orb gradient-orb-2"></div></div></div>
        <div class="login-form-container"><div class="form-header-logo"><div class="form-logo"><img src="/images/logo/nutri.png" alt="Nutriqube logo" /></div><span class="form-brand-name">Nutriqube</span></div><div class="form-wrapper"><div class="form-header"><h2>Create New Password</h2><p>Enter your new password below to reset your account access.</p></div><form id="resetPasswordForm" class="login-form"><input type="hidden" id="resetToken" value=""><div class="form-group"><label for="newPassword" class="form-label"><span>New Password</span></label><div class="form-input-wrapper"><svg class="input-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg><input type="password" id="newPassword" class="form-input" placeholder="Enter your new password" required autocomplete="new-password" minlength="8"><button type="button" class="password-toggle" aria-label="Toggle password visibility"><svg class="icon-show" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path><circle cx="12" cy="12" r="3"></circle></svg><svg class="icon-hide" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="display: none;"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path><line x1="1" y1="1" x2="23" y2="23"></line></svg></button></div></div><div class="form-group"><label for="confirmPassword" class="form-label"><span>Confirm Password</span></label><div class="form-input-wrapper"><svg class="input-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg><input type="password" id="confirmPassword" class="form-input" placeholder="Confirm your new password" required autocomplete="new-password" minlength="8"><button type="button" class="password-toggle" aria-label="Toggle password visibility"><svg class="icon-show" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path><circle cx="12" cy="12" r="3"></circle></svg><svg class="icon-hide" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="display: none;"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path><line x1="1" y1="1" x2="23" y2="23"></line></svg></button></div></div><button type="submit" class="btn btn-primary btn-submit"><span>Reset Password</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"></path></svg></button><div id="alertContainer"></div></form><div class="form-back-link"><p>Remember your password? <a href="/login">Back to sign in</a></p></div><div class="mobile-branding-bottom"><h3>Support When You Need It</h3><p>Need access? <a href="/?contact=open">Contact our team</a></p></div></div></div>
    </div>
    <div id="loadingSpinner" class="loading-overlay" style="display: none;"><div class="spinner"><div class="spinner-ring"></div><div class="spinner-text">Resetting password...</div></div></div>
    <script src="/static/js/config.js?v=8.0"></script>
    <script src="/static/js/auth.js?v=8.0"></script>
    <script src="/static/js/premium.js"></script>
    <script>const urlParams=new URLSearchParams(window.location.search);const token=urlParams.get("token");if(!token){showAlert("Invalid or missing reset token","danger");setTimeout(()=>{window.location.href="/login"},2000)}else{document.getElementById("resetToken").value=token}document.getElementById("resetPasswordForm")?.addEventListener("submit",async(e)=>{e.preventDefault();const newPassword=document.getElementById("newPassword").value;const confirmPassword=document.getElementById("confirmPassword").value;const resetToken=document.getElementById("resetToken").value;const loadingSpinner=document.getElementById("loadingSpinner");const submitBtn=document.querySelector(".btn-submit");if(newPassword!==confirmPassword){showAlert("Passwords do not match","danger");return}if(newPassword.length<8){showAlert("Password must be at least 8 characters","danger");return}if(loadingSpinner)loadingSpinner.style.display="flex";if(submitBtn){submitBtn.disabled=true;submitBtn.innerHTML='<span>Resetting...</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="animation: spin 1s linear infinite;"><circle cx="12" cy="12" r="10"></circle></svg>'}try{const response=await fetch(`${CONFIG.BACKEND.API_URL}/auth/reset-password`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({token:resetToken,new_password:newPassword,confirm_password:confirmPassword})});if(!response.ok){const error=await response.json();throw new Error(error.detail||"Password reset failed")}const data=await response.json();showAlert("Password reset successfully! Redirecting to login...","success");setTimeout(()=>{window.location.href="/login"},2000)}catch(error){showAlert(error.message||"Password reset failed. Please try again.","danger")}finally{if(loadingSpinner)loadingSpinner.style.display="none";if(submitBtn){submitBtn.disabled=false;submitBtn.innerHTML='<span>Reset Password</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"></path></svg>'}}});document.querySelectorAll(".password-toggle").forEach(toggle=>{toggle.addEventListener("click",(e)=>{e.preventDefault();const input=toggle.previousElementSibling;const iconShow=toggle.querySelector(".icon-show");const iconHide=toggle.querySelector(".icon-hide");if(input.type==="password"){input.type="text";iconShow.style.display="none";iconHide.style.display="block"}else{input.type="password";iconShow.style.display="block";iconHide.style.display="none"}})});</script>
</body>
</html>
